package main

import (
	"borealis/api-backend/internal/clusterbootstrap"
	"bytes"
	"context"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
	"syscall"
)

// Proves actual generated bytes and metadata, never a retained file hash. This
// is only the filesystem portion of prepared-host proof; loaded systemd state,
// installed dependencies, firewall rules and stopped consumers remain separate.
func proveBootstrapPrejoinHostFiles(ctx context.Context, expected clusterbootstrap.PreparationExpected, check func(context.Context) error) error {
	if os.Geteuid() != 0 || os.Getegid() != 0 {
		return errBootstrapSource
	}
	root, err := os.OpenRoot("/")
	if err != nil {
		return errBootstrapSource
	}
	defer root.Close()
	return proveBootstrapPrejoinHostFilesWith(ctx, root, expected, check)
}

func proveBootstrapPrejoinHostFilesWith(ctx context.Context, root *os.Root, expected clusterbootstrap.PreparationExpected, check func(context.Context) error) error {
	files, err := bootstrapPrejoinHostFiles(expected)
	if err != nil || root == nil || check == nil || ctx.Err() != nil || check(ctx) != nil {
		return errBootstrapSource
	}
	// Snapshot every ancestor's inode/type/owner/mode, not mtime: unrelated
	// files in shared /etc or /usr directories are outside this fixed inventory.
	before, err := bootstrapHostFileAncestors(root, files)
	if err != nil {
		return errBootstrapSource
	}
	for pass := 0; pass < 2; pass++ {
		for _, file := range files {
			if ctx.Err() != nil || check(ctx) != nil || proveBootstrapHostFile(root, file) != nil {
				return errBootstrapSource
			}
		}
		// This newly prepared K3s directory contains only the two rendered
		// files and their directory. Unknown config/tokens/drop-ins cannot hide
		// behind a matching 10-borealis.yaml or registries.yaml.
		if proveBootstrapHostDirectory(root, "etc/rancher/k3s", map[string]bool{"config.yaml.d": true, "registries.yaml": false}) != nil ||
			proveBootstrapHostDirectory(root, "etc/rancher/k3s/config.yaml.d", map[string]bool{"10-borealis.yaml": false}) != nil {
			return errBootstrapSource
		}
		after, err := bootstrapHostFileAncestors(root, files)
		if err != nil || len(after) != len(before) || ctx.Err() != nil || check(ctx) != nil {
			return errBootstrapSource
		}
		for path, metadata := range before {
			if after[path] != metadata {
				return errBootstrapSource
			}
		}
	}
	return nil
}

func proveBootstrapHostDirectory(root *os.Root, path string, expected map[string]bool) error {
	directory, err := root.OpenFile(path, os.O_RDONLY|syscall.O_DIRECTORY|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return errBootstrapSource
	}
	entries, readErr := directory.ReadDir(len(expected) + 1)
	closeErr := directory.Close()
	if readErr != nil && !errors.Is(readErr, io.EOF) || closeErr != nil || len(entries) != len(expected) {
		return errBootstrapSource
	}
	for _, entry := range entries {
		dir, exists := expected[entry.Name()]
		if !exists || entry.Type()&os.ModeSymlink != 0 || entry.IsDir() != dir {
			return errBootstrapSource
		}
	}
	return nil
}

type bootstrapHostDirectoryIdentity struct {
	device, inode uint64
	uid, gid      uint32
	mode          os.FileMode
}

func bootstrapHostFileAncestors(root *os.Root, files []bootstrapHostFile) (map[string]bootstrapHostDirectoryIdentity, error) {
	identities := map[string]bootstrapHostDirectoryIdentity{}
	for _, file := range files {
		path := ""
		for _, part := range strings.Split(filepath.Dir(file.path), "/") {
			path = filepath.Join(path, part)
			if _, exists := identities[path]; exists {
				continue
			}
			info, err := root.Lstat(path)
			if err != nil || !info.IsDir() || info.Mode().Perm()&0022 != 0 || info.Mode()&(os.ModeSetuid|os.ModeSetgid|os.ModeSticky) != 0 {
				return nil, errBootstrapSource
			}
			owner, ok := info.Sys().(*syscall.Stat_t)
			if !ok || int(owner.Uid) != os.Geteuid() || int(owner.Gid) != os.Getegid() {
				return nil, errBootstrapSource
			}
			if (path == "etc/rancher/k3s" || path == "etc/rancher/k3s/config.yaml.d") && info.Mode().Perm() != 0700 {
				return nil, errBootstrapSource
			}
			identities[path] = bootstrapHostDirectoryIdentity{uint64(owner.Dev), uint64(owner.Ino), owner.Uid, owner.Gid, info.Mode()}
		}
	}
	return identities, nil
}

func proveBootstrapHostFile(root *os.Root, expected bootstrapHostFile) error {
	metadata := func(info os.FileInfo) bool {
		if info == nil || !info.Mode().IsRegular() || info.Mode() != expected.mode || info.Size() != int64(len(expected.data)) {
			return false
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		return ok && int(owner.Uid) == os.Geteuid() && int(owner.Gid) == os.Getegid() && owner.Nlink == 1
	}
	before, err := root.Lstat(expected.path)
	if err != nil || !metadata(before) {
		return errBootstrapSource
	}
	file, err := root.OpenFile(expected.path, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return errBootstrapSource
	}
	held, statErr := file.Stat()
	if statErr != nil || !metadata(held) || !os.SameFile(before, held) {
		file.Close()
		return errBootstrapSource
	}
	// A fixed allocation avoids abandoned growth copies when this shared proof
	// checks private join tokens. Clear every owned byte on all exits.
	raw := make([]byte, len(expected.data)+1)
	defer clear(raw)
	n, readErr := io.ReadFull(file, raw)
	last, statErr := file.Stat()
	closeErr := file.Close()
	after, pathErr := root.Lstat(expected.path)
	if (readErr != io.EOF && readErr != io.ErrUnexpectedEOF) || n != len(expected.data) || statErr != nil || closeErr != nil || pathErr != nil || !bytes.Equal(raw[:n], expected.data) ||
		!metadata(last) || !metadata(after) || !os.SameFile(held, last) || !os.SameFile(held, after) ||
		!held.ModTime().Equal(last.ModTime()) || !held.ModTime().Equal(after.ModTime()) {
		return errBootstrapSource
	}
	return nil
}
